cd /tmp/fetchtest && cat Cargo.toml && cat > src/main.rs <<'EOF'
use rusqlite::Connection;
fn main() {
    let conn = Connection::open_in_memory().unwrap();
    conn.execute_batch("CREATE TABLE t(id INTEGER PRIMARY KEY, v TEXT); INSERT INTO t(v) VALUES('hi');").unwrap();
    let v: String = conn.query_row("SELECT v FROM t LIMIT 1", [], |r| r.get(0)).unwrap();
    println!("db says: {v}");
    let server = tiny_http::Server::http("127.0.0.1:18923").unwrap();
    std::thread::spawn(move || {
        for rq in server.incoming_requests() {
            let _ = rq.respond(tiny_http::Response::from_string("hello"));
        }
    });
    let body = ureq_get();
    println!("http says: {body}");
}
fn ureq_get() -> String {
    use std::io::{Read, Write};
    let mut s = std::net::TcpStream::connect("127.0.0.1:18923").unwrap();
    s.write_all(b"GET / HTTP/1.1\r\nHost: x\r\nConnection: close\r\n\r\n").unwrap();
    let mut buf = String::new();
    s.read_to_string(&mut buf).unwrap();
    buf
}
EOF
