use std::sync::Arc;

fn main() {
    let port: u16 = std::env::var("PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(3000);
    let username = std::env::var("QUIZZY_MODERATOR_USERNAME").unwrap_or_default();
    let password = std::env::var("QUIZZY_MODERATOR_PASSWORD").unwrap_or_default();

    std::fs::create_dir_all("storage").expect("create storage dir");
    let db_path = std::env::var("QUIZZY_DATABASE_PATH").unwrap_or_else(|_| "storage/quizzy.db".to_string());
    {
        let conn = rusqlite::Connection::open(&db_path).expect("open db");
        db::migrate(&conn).expect("migrate");
    }

    let state = Arc::new(routes::State { db_path, username, password });

    let server = tiny_http::Server::http(("0.0.0.0", port)).expect("bind");
    println!("Quizzy listening on 0.0.0.0:{port}");
    let server = Arc::new(server);
    let mut handles = Vec::new();
    for _ in 0..16 {
        let server = server.clone();
        let state = state.clone();
        handles.push(std::thread::spawn(move || loop {
            match server.recv() {
                Ok(rq) => httpd::dispatch(rq, &state),
                Err(_) => continue,
            }
        }));
    }
    for h in handles { let _ = h.join(); }
}
