```rust
pub fn parse_urlencoded(data: &[u8]) -> Vec<(String, String)> {
    let s = String::from_utf8_lossy(data);
    s.split('&').filter(|p| !p.is_empty()).map(|p| {
        let mut it = p.splitn(2, '=');
        let k = url_decode(it.next().unwrap_or(""));
        let v = url_decode(it.next().unwrap_or(""));
        (k, v)
    }).collect()
}

pub fn url_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'+' => { out.push(b' '); i += 1; }
            b'%' if i + 2 < bytes.len() => {
                let h = hex(bytes[i+1]); let l = hex(bytes[i+2]);
                if let (Some(h), Some(l)) = (h, l) { out.push(h << 4 | l); i += 3; }
                else { out.push(bytes[i]); i += 1; }
            }
            c => { out.push(c); i += 1; }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}
```

Careful with `i + 2 < bytes.len()` — should be `i + 2 <= bytes.len() - 1`, i.e., `i + 2 < len` means index i+2 valid. Correct: bytes[i+2] requires i+2 <= len-1 → i+2 < len. OK as written.

