fn moderate(req, state, segs) -> Resp {
    if !authorized(req, state) { return Resp::unauthorized(); }
    let conn = db::connect(&state.db_path).unwrap();
    match (method, segs) {
        ("GET", ["moderate"]) => quiz list
        ("GET", ["moderate","quizzes","new"]) => quiz form (new)
        ("POST", ["moderate","quizzes"]) => create quiz
        ("GET", ["moderate","quizzes", id]) => quiz page
        ("GET", ["moderate","quizzes", id, "edit"]) => quiz form (edit)
        ("POST", ["moderate","quizzes", id]) => update quiz
        ("POST", ["moderate","quizzes", id, "delete"]) => delete quiz
        ("GET", ["moderate","quizzes", id, "questions", "new"]) => question form new (4 rows)
        ("POST", ["moderate","quizzes", id, "questions"]) => create question (or add_option re-render)
        ("GET", ["moderate","quizzes", id, "questions", qid, "edit"]) => question form edit
        ("POST", ["moderate","quizzes", id, "questions", qid]) => update question (or add_option re-render)
        ("POST", ["moderate","quizzes", id, "questions", qid, "delete"]) => delete question
        ("POST", ["moderate","quizzes", id, "questions", qid, "move"]) => move
        ("POST", ["moderate","quizzes", id, "questions", qid, "active"]) => toggle active
        ("GET", ["moderate","quizzes", id, "preview"]) => preview question n
        ("POST", ["moderate","quizzes", id, "preview", "answer"]) => feedback
        ("GET", ["moderate","quizzes", id, "preview", "score"]) => score page
        _ => Resp::not_found()
    }
}
```

Note conflict: ["moderate","quizzes", id, "questions", "new"] vs qid parse — "new" handled before qid parse. Since I match string slices in order, put "new" pattern first. In Rust match, `["moderate","quizzes", id, "questions", qid, "edit"]` with id/qid as binding patterns — order matters; literal "new" arm before catch-all id arms? "new" appears at questions level: `["moderate","quizzes", id, "questions", "new"]` (5 segs, last literal) vs `["moderate","quizzes", id, "questions", qid, "edit"]` (6 segs) — different lengths, no conflict. And `["moderate","quizzes","new"]` (3 segs, literal) vs `["moderate","quizzes", id]` — put literal first; match arms are tried in order, so put ("GET", ["moderate","quizzes","new"]) before ("GET", ["moderate","quizzes", id]). In Rust, `["moderate", "quizzes", id]` binds anything including "new" — so order is essential. Fine.

