//! Thin HTTP plumbing on top of tiny_http: request parsing (query string,
//! urlencoded bodies, Basic auth header) and response construction.

use std::io::Read;
use tiny_http::{Header, Request as TinyRequest, Response, StatusCode};

pub struct Request {
    pub method: String,
    pub path: String,
    pub query: Vec<(String, String)>,
    pub form: Vec<(String, String)>,
    pub authorization: Option<String>,
}

impl Request {
    /// Look up a parameter: form body first, then the query string.
    pub fn param(&self, key: &str) -> Option<&str> {
        self.form
            .iter()
            .chain(self.query.iter())
            .find(|(k, _)| k == key)
            .map(|(_, v)| v.as_str())
    }

    pub fn has_param(&self, key: &str) -> bool {
        self.param(key).is_some()
    }
}

pub struct Resp {
    pub status: u16,
    pub content_type: &'static str,
    pub body: Vec<u8>,
    pub extra_headers: Vec<(String, String)>,
}

impl Resp {
    pub fn html(body: String) -> Resp {
        Resp { status: 200, content_type: "text/html; charset=utf-8", body: body.into_bytes(), extra_headers: vec![] }
    }

    pub fn text(status: u16, body: &str) -> Resp {
        Resp { status, content_type: "text/plain; charset=utf-8", body: body.as_bytes().to_vec(), extra_headers: vec![] }
    }

    /// See Other: the response to every successful POST (post/redirect/get).
    pub fn redirect(location: &str) -> Resp {
        Resp {
            status: 303,
            content_type: "text/plain; charset=utf-8",
            body: Vec::new(),
            extra_headers: vec![("Location".to_string(), location.to_string())],
        }
    }

    pub fn not_found() -> Resp {
        Resp::text(404, "Not found")
    }

    pub fn unauthorized() -> Resp {
        Resp {
            status: 401,
            content_type: "text/plain; charset=utf-8",
            body: b"Authentication required".to_vec(),
            extra_headers: vec![(
                "WWW-Authenticate".to_string(),
                "Basic realm=\"Quizzy moderator\", charset=\"UTF-8\"".to_string(),
            )],
        }
    }
}

/// Entry point called by the worker threads: parse, route, respond.
pub fn dispatch(mut rq: TinyRequest, route: &dyn Fn(&Request) -> Resp) {
    let method = rq.method().to_string();
    let url = rq.url().to_string();
    let authorization = rq
        .headers()
        .iter()
        .find(|h| h.field.equiv("Authorization"))
        .map(|h| h.value.as_str().to_string());

    let mut body = Vec::new();
    if matches!(method.as_str(), "POST" | "PUT" | "PATCH" | "DELETE") {
        let _ = rq.as_reader().take(8 * 1024 * 1024).read_to_end(&mut body);
    }

    let (path, raw_query) = match url.split_once('?') {
        Some((p, q)) => (p.to_string(), q.to_string()),
        None => (url, String::new()),
    };

    let req = Request {
        method,
        path,
        query: parse_urlencoded(raw_query.as_bytes()),
        form: parse_urlencoded(&body),
        authorization,
    };

    let resp = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| route(&req))) {
        Ok(resp) => resp,
        Err(_) => Resp::text(500, "Internal server error"),
    };
    respond(rq, resp);
}

fn respond(rq: TinyRequest, resp: Resp) {
    let mut r = Response::from_data(resp.body).with_status_code(StatusCode(resp.status));
    if let Ok(h) = Header::from_bytes("Content-Type", resp.content_type) {
        r.add_header(h);
    }
    for (name, value) in &resp.extra_headers {
        if let Ok(h) = Header::from_bytes(name.as_str(), value.as_str()) {
            r.add_header(h);
        }
    }
    let _ = rq.respond(r);
}

/// Parse an `application/x-www-form-urlencoded` payload (or query string).
pub fn parse_urlencoded(data: &[u8]) -> Vec<(String, String)> {
    let text = String::from_utf8_lossy(data);
    text.split('&')
        .filter(|pair| !pair.is_empty())
        .map(|pair| {
            let (k, v) = pair.split_once('=').unwrap_or((pair, ""));
            (url_decode(k), url_decode(v))
        })
        .collect()
}

fn url_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' if i + 2 < bytes.len() => {
                match (hex_val(bytes[i + 1]), hex_val(bytes[i + 2])) {
                    (Some(h), Some(l)) => {
                        out.push((h << 4) | l);
                        i += 3;
                    }
                    _ => {
                        out.push(bytes[i]);
                        i += 1;
                    }
                }
            }
            c => {
                out.push(c);
                i += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn hex_val(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

/// Decode the `Authorization: Basic ...` header into (username, password).
pub fn basic_credentials(header: &str) -> Option<(String, String)> {
    let token = header.strip_prefix("Basic ").or_else(|| {
        // tolerate lowercase scheme
        if header.len() > 6 && header[..6].eq_ignore_ascii_case("basic ") {
            Some(&header[6..])
        } else {
            None
        }
    })?;
    let decoded = base64_decode(token.trim())?;
    let text = String::from_utf8_lossy(&decoded);
    let (user, pass) = text.split_once(':')?;
    Some((user.to_string(), pass.to_string()))
}

fn base64_decode(input: &str) -> Option<Vec<u8>> {
    fn val(c: u8) -> Option<u8> {
        match c {
            b'A'..=b'Z' => Some(c - b'A'),
            b'a'..=b'z' => Some(c - b'a' + 26),
            b'0'..=b'9' => Some(c - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }
    let mut out = Vec::with_capacity(input.len() * 3 / 4);
    let mut acc: u32 = 0;
    let mut nbits = 0;
    for &c in input.as_bytes() {
        if c == b'=' || c == b'\n' || c == b'\r' || c == b' ' {
            continue;
        }
        let v = val(c)? as u32;
        acc = (acc << 6) | v;
        nbits += 6;
        if nbits >= 8 {
            nbits -= 8;
            out.push((acc >> nbits) as u8);
        }
    }
    Some(out)
}
