//! HTML rendering. Every page is built from the design system's classes
//! (docs/mockups/quizzy.css). All user content goes through `esc`.

use crate::db::{Question, Quiz, QuizSummary};

pub fn esc(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => out.push_str("&amp;"),
            '<' => out.push_str("&lt;"),
            '>' => out.push_str("&gt;"),
            '"' => out.push_str("&quot;"),
            '\'' => out.push_str("&#39;"),
            _ => out.push(c),
        }
    }
    out
}

fn letter(i: usize) -> char {
    let b = b'A' + (i % 26) as u8;
    b as char
}

/// Moderator chrome: header with logo + tag, main column.
fn admin_layout(title: &str, body: &str) -> String {
    format!(
        r#"<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Quizzy · {title}</title>
