          </div>
        </div>
      </li>
"#,
            quiz_id = quiz.id,
            qid = q.id,
            text = esc(&q.text),
        ));
    }
    let list = if questions.is_empty() {
        r#"      <div class="empty">No questions yet. Add the first one!</div>"#.to_string()
    } else {
        format!("      <ol class=\"question-list\">\n{items}      </ol>")
    };
    let body = format!(
        r#"    <div class="breadcrumbs"><a href="/moderate">← All quizzes</a></div>
    <div class="page-head">
      <div>
        <h1>{title}</h1>
        <div class="meta mt-2">{active_count} of {total} questions active · <a href="/moderate/quizzes/{id}/edit">Settings</a></div>
