        <a class="btn" href="/moderate/quizzes/{id}/questions/new">Add question</a>
      </div>
{list}
    </section>"#,
        title = esc(&quiz.title),
        id = quiz.id,
        total = questions.len(),
    );
    admin_layout(&quiz.title, &body)
}

// ---------- Question form ----------

pub struct OptionRow {
