fn play_options(options: &[crate::db::Opt], revealed: bool, picked: Option<i64>, form: Option<(&str, usize, i64)>) -> String {
    let mut inner = String::new();
    let hidden = match form {
        Some((_, n, score)) => format!(
            r#"<input type="hidden" name="n" value="{n}"><input type="hidden" name="score" value="{score}">"#
        ),
        None => String::new(),
    };
    for (j, o) in options.iter().enumerate() {
        let mut classes = String::from("play-option");
        if revealed && o.correct {
            classes.push_str(" is-correct");
        }
        if picked == Some(o.id) {
            classes.push_str(" is-picked");
        }
        let content = format!(
            r#"<span class="play-option__letter">{letter}</span><span class="play-option__title">{text}</span>"#,
