        if form.is_some() {
            inner.push_str(&format!(
                r#"<button class="{classes}" type="submit" name="option" value="{id}">{content}</button>"#,
                id = o.id,
            ));
        } else {
            inner.push_str(&format!(r#"<div class="{classes}">{content}</div>"#));
        }
    }
    let options_class = if revealed { "play-options is-locked is-revealed" } else { "play-options" };
    match form {
        Some((action, _, _)) => format!(
            r#"<div class="{options_class}"><form method="post" action="{action}">{hidden}{inner}</form></div>"#
        ),
        None => format!(r#"<div class="{options_class}">{inner}</div>"#),
    }
}

/// One active question with its options as buttons.
pub fn preview_question(quiz: &Quiz, q: &Question, n: usize, total: usize, score: i64) -> String {
    let action = format!("/moderate/quizzes/{}/preview/answer", quiz.id);
    let body = format!(
        r#"      <div class="play-question__num">Question {n} of {total}</div>
      <div class="play-question__body">{text}</div>
      {options}
      <div class="buttons" style="margin-top: 24px">
        <a class="btn btn--ghost btn--sm" href="/moderate/quizzes/{id}/preview">Start over</a>
      </div>"#,
        text = esc(&q.text),
        options = play_options(&q.options, false, None, Some((&action, n, score))),
        id = quiz.id,
    );
    play_layout(quiz, &body)
}

/// Feedback after picking an option: reveal correct options, show verdict.
#[allow(clippy::too_many_arguments)]
pub fn preview_feedback(
    quiz: &Quiz,
    q: &Question,
    n: usize,
    total: usize,
    picked: i64,
    correct: bool,
    new_score: i64,
) -> String {
    let (status_class, verdict) =
        if correct { ("play-status play-status--right", "Correct!") } else { ("play-status play-status--wrong", "Wrong!") };
    let next = if n < total {
        format!(
            r#"<a class="btn btn--pink" href="/moderate/quizzes/{id}/preview?n={next_n}&amp;score={score}">Next question</a>"#,
            id = quiz.id,
            next_n = n + 1,
            score = new_score,
        )
    } else {
        format!(
            r#"<a class="btn btn--pink" href="/moderate/quizzes/{id}/preview/score?score={score}">See score</a>"#,
            id = quiz.id,
            score = new_score,
        )
    };
    let body = format!(
        r#"      <div class="play-question__num">Question {n} of {total}</div>
      <div class="play-question__body">{text}</div>
      {options}
      <div class="{status_class}" role="status">{verdict}</div>
      <div class="buttons" style="margin-top: 24px">
        {next}
        <a class="btn btn--ghost btn--sm" href="/moderate/quizzes/{id}/preview">Start over</a>
      </div>"#,
        text = esc(&q.text),
        options = play_options(&q.options, true, Some(picked), None),
        id = quiz.id,
    );
    play_layout(quiz, &body)
}

pub fn preview_score(quiz: &Quiz, score: i64, total: usize) -> String {
    let body = format!(
        r#"      <div class="card result-card">
        <div class="result-card__label">Result</div>
        <div class="result-card__score">Score: {score}/{total}</div>
      </div>
      <div class="buttons" style="margin-top: 24px; justify-content: center">
        <a class="btn btn--pink" href="/moderate/quizzes/{id}/preview">Start over</a>
      </div>"#,
        id = quiz.id,
    );
    play_layout(quiz, &body)
}

pub fn preview_empty(quiz: &Quiz) -> String {
    let body = format!(
        r#"      <div class="card">
        <p style="margin:0">This quiz has no active questions yet.</p>
      </div>
      <div class="buttons" style="margin-top: 24px">
        <a class="btn btn--ghost" href="/moderate/quizzes/{id}">Back to quiz</a>
      </div>"#,
        id = quiz.id,
    );
    play_layout(quiz, &body)
}
