//! Quizzy — a live quiz for conference talks. This is the moderator release:
//! preparing quizzes, questions and options, plus a playable preview.
//!
//! Run with: PORT=3000 SECRET_KEY_BASE=... QUIZZY_MODERATOR_USERNAME=... \
//!           QUIZZY_MODERATOR_PASSWORD=... ./bin/serve
//!
//! SECRET_KEY_BASE is accepted for forward compatibility (session signing in
//! later releases); this release keeps no session state.

mod db;
mod httpd;
mod routes;
mod views;

use std::sync::Arc;

fn main() {
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(3000);
    let state = Arc::new(routes::State {
        db_path: std::env::var("QUIZZY_DATABASE_PATH")
            .unwrap_or_else(|_| "storage/quizzy.db".to_string()),
        moderator_username: std::env::var("QUIZZY_MODERATOR_USERNAME").unwrap_or_default(),
        moderator_password: std::env::var("QUIZZY_MODERATOR_PASSWORD").unwrap_or_default(),
    });

    // Everything the app stores lives under storage/.
    if let Some(parent) = std::path::Path::new(&state.db_path).parent() {
        std::fs::create_dir_all(parent).expect("cannot create storage directory");
    }
    {
        let conn = db::connect(&state.db_path).expect("cannot open the database");
        db::migrate(&conn).expect("cannot migrate the database");
    }

    let server = tiny_http::Server::http(("0.0.0.0", port))
        .unwrap_or_else(|e| panic!("cannot listen on port {port}: {e}"));
    println!("Quizzy is ready on http://0.0.0.0:{port}");
    let server = Arc::new(server);

    let workers = std::thread::available_parallelism().map(|n| n.get().clamp(8, 32)).unwrap_or(8);
    let mut handles = Vec::new();
    for _ in 0..workers {
        let server = Arc::clone(&server);
        let state = Arc::clone(&state);
        handles.push(std::thread::spawn(move || loop {
            match server.recv() {
                Ok(request) => {
                    let state = Arc::clone(&state);
                    httpd::dispatch(request, &move |req| routes::handle(req, &state));
                }
                Err(_) => continue,
            }
        }));
    }
    for h in handles {
        let _ = h.join();
    }
}
